// Time-series momentum: sign of the 60-bar return, volatility scaled
const look = 60, vol = ta.stdev(close, 20);
const pos = close.map((c, i) => i < look ? 0 : Math.sign(c - close[i - look]) * Math.min(1, 0.01 / Math.max(1e-9, vol[i] / c)));
return { plots: { 'Mom 60': close.map((c, i) => i < look ? null : (c / close[i - look] - 1) * 100) }, positions: pos, pane: 'lower' };

// Fade 2Ï excursions, exit at midline
const mid = ta.sma(close, 20), sd = ta.stdev(close, 20);
let p = 0; const pos = close.map((c, i) => { if (mid[i] == null) return 0; if (c > mid[i] + 2 * sd[i]) p = -1; else if (c < mid[i] - 2 * sd[i]) p = 1; else if ((p > 0 && c >= mid[i]) || (p < 0 && c <= mid[i])) p = 0; return p; });
return { plots: { Upper: mid.map((m, i) => m == null ? null : m + 2 * sd[i]), Lower: mid.map((m, i) => m == null ? null : m - 2 * sd[i]), Mid: mid }, positions: pos };

// EMA trend direction Ã inverse-vol sizing (target 1% per-bar vol)
const fast = ta.ema(close, 20), slow = ta.ema(close, 80), vol = ta.stdev(close, 20);
const pos = close.map((c, i) => slow[i] == null ? 0 : Math.sign(fast[i] - slow[i]) * Math.min(1.5, 0.01 / Math.max(1e-9, vol[i] / c)));
return { plots: { 'EMA 20': fast, 'EMA 80': slow }, positions: pos };

// Hold only in the last third of each day's bars (proxy for overnight/close drift)
const pos = bars.map(b => { const h = new Date(b.t * 1000).getUTCHours(); return (h >= 18 || h < 2) ? 1 : 0; });
return { plots: { 'Session filter': pos.map(p => p * 100) }, positions: pos, pane: 'lower' };

// RSI(2) pullback in an uptrend
const r = ta.rsi(close, 2), sma200 = ta.sma(close, Math.min(200, Math.floor(close.length / 2)));
let p = 0; const pos = close.map((c, i) => { if (r[i] == null || sma200[i] == null) return 0; if (c > sma200[i] && r[i] < 10) p = 1; else if (p && r[i] > 65) p = 0; return p; });
return { plots: { 'RSI 2': r }, positions: pos, pane: 'lower' };

// Donchian 20/10 breakout
const hi = ta.highest(high, 20), lo = ta.lowest(low, 20), xh = ta.highest(high, 10), xl = ta.lowest(low, 10);
let p = 0; const pos = close.map((c, i) => { if (hi[i] == null) return 0; if (c > hi[i - 1]) p = 1; else if (c < lo[i - 1]) p = -1; else if ((p > 0 && c < xl[i - 1]) || (p < 0 && c > xh[i - 1])) p = 0; return p; });
return { plots: { 'DC high': hi, 'DC low': lo }, positions: pos };

// Fade 1.5Ï deviations from session VWAP
const v = ta.vwap(bars), dev = close.map((c, i) => c - v[i]), sd = ta.stdev(dev, 30);
let p = 0; const pos = close.map((c, i) => { if (sd[i] == null) return 0; if (dev[i] > 1.5 * sd[i]) p = -1; else if (dev[i] < -1.5 * sd[i]) p = 1; else if (Math.abs(dev[i]) < 0.2 * sd[i]) p = 0; return p; });
return { plots: { VWAP: v }, positions: pos };

// Regime filter: long only when above long mean AND vol not expanding
const m = ta.sma(close, Math.min(200, Math.floor(close.length / 2))), v = ta.stdev(close, 20), vslow = ta.sma(v, 40);
const pos = close.map((c, i) => (m[i] == null || vslow[i] == null) ? 0 : (c > m[i] && v[i] < 1.3 * vslow[i]) ? 1 : (c < m[i] && v[i] > 1.3 * vslow[i]) ? -0.5 : 0);
return { plots: { 'Long mean': m }, positions: pos };

// 4-week momentum, skip last 2 bars
const look = 28 * 4, skip = 2;
const mom = close.map((c, i) => i < look + skip ? null : close[i - skip] / close[i - look - skip] - 1);
const pos = mom.map(m => m == null ? 0 : m > 0 ? 1 : -0.5);
return { plots: { 'Mom %': mom.map(m => m == null ? null : m * 100) }, positions: pos, pane: 'lower' };

// z-score of spread vs 60-bar mean
const m = ta.sma(close, 60), sd = ta.stdev(close, 60), z = close.map((c, i) => sd[i] ? (c - m[i]) / sd[i] : null);
let p = 0; const pos = z.map(v => { if (v == null) return 0; if (v > 2) p = -1; else if (v < -2) p = 1; else if (Math.abs(v) < 0.25) p = 0; return p; });
return { plots: { z }, positions: pos, pane: 'lower' };
